-- Visionary X Operations — core schema
-- Conventions:
--   * Primary keys are opaque TEXT ids generated by the Worker.
--   * *_at columns are UTC ISO-8601 timestamps (e.g. 2026-10-14T09:30:00.000Z).
--   * *_date columns are calendar dates (YYYY-MM-DD) interpreted in the company timezone (Asia/Kolkata).
--   * is_seed = 1 marks development sample data so it can never be confused with real records.
--   * D1 enforces foreign keys. Multi-statement writes use db.batch() for atomicity.

-- ───────────────────────────── Identity & access ─────────────────────────────

CREATE TABLE users (
  id                 TEXT PRIMARY KEY,
  email              TEXT NOT NULL COLLATE NOCASE UNIQUE,
  name               TEXT NOT NULL,
  password_hash      TEXT,                       -- NULL until the account is activated
  status             TEXT NOT NULL DEFAULT 'invited' CHECK (status IN ('invited','active','deactivated')),
  mfa_enabled        INTEGER NOT NULL DEFAULT 0 CHECK (mfa_enabled IN (0,1)),
  mfa_secret_enc     TEXT,                       -- AES-GCM encrypted TOTP secret
  mfa_pending_enc    TEXT,                       -- secret awaiting enrolment confirmation
  mfa_last_step      INTEGER,                    -- last accepted TOTP time-step (replay protection)
  failed_login_count INTEGER NOT NULL DEFAULT 0,
  locked_until       TEXT,
  password_changed_at TEXT,
  last_login_at      TEXT,
  avatar_color       TEXT,
  is_seed            INTEGER NOT NULL DEFAULT 0,
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL,
  deactivated_at     TEXT
);
CREATE INDEX idx_users_status ON users(status);

CREATE TABLE roles (
  id           TEXT PRIMARY KEY,
  key          TEXT NOT NULL UNIQUE,
  name         TEXT NOT NULL,
  description  TEXT NOT NULL DEFAULT '',
  is_system    INTEGER NOT NULL DEFAULT 0,
  requires_mfa INTEGER NOT NULL DEFAULT 0,
  rank         INTEGER NOT NULL DEFAULT 100,     -- lower = more privileged; used to stop privilege escalation
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL
);

CREATE TABLE permissions (
  key         TEXT PRIMARY KEY,
  label       TEXT NOT NULL,
  category    TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT ''
);

CREATE TABLE role_permissions (
  role_id        TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  permission_key TEXT NOT NULL REFERENCES permissions(key) ON DELETE CASCADE,
  PRIMARY KEY (role_id, permission_key)
);

CREATE TABLE user_roles (
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role_id    TEXT NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,
  granted_by TEXT REFERENCES users(id),
  granted_at TEXT NOT NULL,
  PRIMARY KEY (user_id, role_id)
);
CREATE INDEX idx_user_roles_role ON user_roles(role_id);

CREATE TABLE sessions (
  id            TEXT PRIMARY KEY,
  token_hash    TEXT NOT NULL UNIQUE,            -- SHA-256 of the cookie token; raw token never stored
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  csrf_token    TEXT NOT NULL,
  mfa_state     TEXT NOT NULL DEFAULT 'none' CHECK (mfa_state IN ('none','pending','verified','enrol_required')),
  created_at    TEXT NOT NULL,
  last_seen_at  TEXT NOT NULL,
  expires_at    TEXT NOT NULL,                   -- absolute expiry
  revoked_at    TEXT,
  revoked_reason TEXT,
  ip            TEXT,
  user_agent    TEXT
);
CREATE INDEX idx_sessions_user ON sessions(user_id, revoked_at);

CREATE TABLE auth_tokens (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  purpose    TEXT NOT NULL CHECK (purpose IN ('activation','password_reset')),
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  used_at    TEXT,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL
);
CREATE INDEX idx_auth_tokens_user ON auth_tokens(user_id, purpose);

CREATE TABLE mfa_recovery_codes (
  id        TEXT PRIMARY KEY,
  user_id   TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  code_hash TEXT NOT NULL,
  used_at   TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_mfa_recovery_user ON mfa_recovery_codes(user_id);

CREATE TABLE rate_limits (
  key          TEXT PRIMARY KEY,
  window_start INTEGER NOT NULL,
  count        INTEGER NOT NULL
);

-- ───────────────────────────── Organisation ─────────────────────────────

CREATE TABLE departments (
  id           TEXT PRIMARY KEY,
  name         TEXT NOT NULL UNIQUE COLLATE NOCASE,
  code         TEXT NOT NULL UNIQUE COLLATE NOCASE,
  description  TEXT NOT NULL DEFAULT '',
  head_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  is_seed      INTEGER NOT NULL DEFAULT 0,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  archived_at  TEXT
);

CREATE TABLE employee_profiles (
  user_id                 TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  employee_code           TEXT NOT NULL UNIQUE,
  designation             TEXT NOT NULL DEFAULT '',
  department_id           TEXT REFERENCES departments(id) ON DELETE SET NULL,
  manager_user_id         TEXT REFERENCES users(id) ON DELETE SET NULL,
  work_phone              TEXT,
  -- Sensitive HR fields: only returned to roles holding employees.read_sensitive
  personal_phone          TEXT,
  personal_email          TEXT,
  date_of_birth           TEXT,
  address                 TEXT,
  emergency_contact_name  TEXT,
  emergency_contact_phone TEXT,
  joining_date            TEXT,
  exit_date               TEXT,
  employment_type         TEXT NOT NULL DEFAULT 'full_time' CHECK (employment_type IN ('full_time','part_time','contract','intern')),
  employment_status       TEXT NOT NULL DEFAULT 'active' CHECK (employment_status IN ('active','probation','notice','exited')),
  weekly_capacity_hours   REAL CHECK (weekly_capacity_hours IS NULL OR weekly_capacity_hours BETWEEN 0 AND 80),
  created_at              TEXT NOT NULL,
  updated_at              TEXT NOT NULL
);
CREATE INDEX idx_employee_dept ON employee_profiles(department_id);
CREATE INDEX idx_employee_manager ON employee_profiles(manager_user_id);

CREATE TABLE employee_skills (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  skill   TEXT NOT NULL COLLATE NOCASE,
  PRIMARY KEY (user_id, skill)
);

CREATE TABLE service_categories (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE COLLATE NOCASE,
  active     INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL
);

-- ───────────────────────────── CRM ─────────────────────────────

CREATE TABLE clients (
  id                 TEXT PRIMARY KEY,
  reference          TEXT NOT NULL UNIQUE,
  name               TEXT NOT NULL,
  organization       TEXT,
  industry           TEXT,
  email              TEXT COLLATE NOCASE,
  phone              TEXT,
  website            TEXT,
  address            TEXT,
  status             TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('lead','active','on_hold','inactive','archived')),
  account_manager_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  notes              TEXT NOT NULL DEFAULT '',
  is_seed            INTEGER NOT NULL DEFAULT 0,
  created_by         TEXT REFERENCES users(id),
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL,
  archived_at        TEXT
);
CREATE UNIQUE INDEX uq_clients_email_active ON clients(email) WHERE email IS NOT NULL AND archived_at IS NULL;
CREATE INDEX idx_clients_status ON clients(status);
CREATE INDEX idx_clients_manager ON clients(account_manager_id);

CREATE TABLE client_service_categories (
  client_id           TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  service_category_id TEXT NOT NULL REFERENCES service_categories(id) ON DELETE CASCADE,
  PRIMARY KEY (client_id, service_category_id)
);

CREATE TABLE client_contacts (
  id         TEXT PRIMARY KEY,
  client_id  TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  name       TEXT NOT NULL,
  title      TEXT,
  email      TEXT COLLATE NOCASE,
  phone      TEXT,
  is_primary INTEGER NOT NULL DEFAULT 0,
  notes      TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_client_contacts_client ON client_contacts(client_id);
CREATE UNIQUE INDEX uq_client_contacts_email ON client_contacts(client_id, email) WHERE email IS NOT NULL;

CREATE TABLE client_interactions (
  id          TEXT PRIMARY KEY,
  client_id   TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  project_id  TEXT REFERENCES projects(id) ON DELETE SET NULL,
  kind        TEXT NOT NULL CHECK (kind IN ('meeting','call','email','note','requirement')),
  subject     TEXT NOT NULL,
  body        TEXT NOT NULL DEFAULT '',
  occurred_at TEXT NOT NULL,
  created_by  TEXT REFERENCES users(id),
  created_at  TEXT NOT NULL
);
CREATE INDEX idx_client_interactions_client ON client_interactions(client_id, occurred_at);

-- ───────────────────────────── Projects ─────────────────────────────

CREATE TABLE projects (
  id                  TEXT PRIMARY KEY,
  reference           TEXT NOT NULL UNIQUE,
  name                TEXT NOT NULL,
  client_id           TEXT NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,
  manager_id          TEXT REFERENCES users(id) ON DELETE SET NULL,
  service_category_id TEXT REFERENCES service_categories(id) ON DELETE SET NULL,
  description         TEXT NOT NULL DEFAULT '',
  scope               TEXT NOT NULL DEFAULT '',
  start_date          TEXT,
  target_date         TEXT,
  completed_at        TEXT,
  status              TEXT NOT NULL DEFAULT 'planning' CHECK (status IN ('planning','not_started','in_progress','on_hold','at_risk','delayed','in_review','completed','archived')),
  priority            TEXT NOT NULL DEFAULT 'medium' CHECK (priority IN ('low','medium','high','urgent')),
  progress_mode       TEXT NOT NULL DEFAULT 'equal' CHECK (progress_mode IN ('equal','effort','milestone')),
  progress            REAL NOT NULL DEFAULT 0,  -- derived; recalculated server-side from tasks, never user-entered
  estimated_hours     REAL,
  client_status_note  TEXT NOT NULL DEFAULT '',  -- approved, client-facing status line
  next_task_number    INTEGER NOT NULL DEFAULT 1,
  closure_approved_by TEXT REFERENCES users(id),
  closure_approved_at TEXT,
  is_seed             INTEGER NOT NULL DEFAULT 0,
  created_by          TEXT REFERENCES users(id),
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  archived_at         TEXT
);
CREATE INDEX idx_projects_client ON projects(client_id);
CREATE INDEX idx_projects_manager ON projects(manager_id);
CREATE INDEX idx_projects_status ON projects(status);

CREATE TABLE project_members (
  project_id     TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  user_id        TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role           TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('manager','lead','member','viewer')),
  can_review     INTEGER NOT NULL DEFAULT 0,
  responsibility TEXT NOT NULL DEFAULT '',
  added_by       TEXT REFERENCES users(id),
  added_at       TEXT NOT NULL,
  PRIMARY KEY (project_id, user_id)
);
CREATE INDEX idx_project_members_user ON project_members(user_id);

CREATE TABLE project_status_history (
  id          TEXT PRIMARY KEY,
  project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  from_status TEXT,
  to_status   TEXT NOT NULL,
  note        TEXT NOT NULL DEFAULT '',
  changed_by  TEXT REFERENCES users(id),
  changed_at  TEXT NOT NULL
);
CREATE INDEX idx_project_status_history ON project_status_history(project_id, changed_at);

CREATE TABLE project_progress_snapshots (
  id              TEXT PRIMARY KEY,
  project_id      TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  progress        REAL NOT NULL,
  completed_units REAL NOT NULL,
  total_units     REAL NOT NULL,
  recorded_at     TEXT NOT NULL
);
CREATE INDEX idx_progress_snapshots ON project_progress_snapshots(project_id, recorded_at);

CREATE TABLE project_updates (
  id           TEXT PRIMARY KEY,
  project_id   TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title        TEXT NOT NULL,
  body         TEXT NOT NULL DEFAULT '',
  client_visible INTEGER NOT NULL DEFAULT 0,
  approved_by  TEXT REFERENCES users(id),
  approved_at  TEXT,
  created_by   TEXT REFERENCES users(id),
  created_at   TEXT NOT NULL
);
CREATE INDEX idx_project_updates ON project_updates(project_id, created_at);

CREATE TABLE milestones (
  id            TEXT PRIMARY KEY,
  project_id    TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title         TEXT NOT NULL,
  description   TEXT NOT NULL DEFAULT '',
  due_date      TEXT,
  weight        REAL NOT NULL DEFAULT 1 CHECK (weight > 0),
  status        TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','in_progress','achieved','missed')),
  achieved_at   TEXT,
  client_visible INTEGER NOT NULL DEFAULT 1,
  sort_order    INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE INDEX idx_milestones_project ON milestones(project_id, sort_order);

CREATE TABLE milestone_dependencies (
  milestone_id  TEXT NOT NULL REFERENCES milestones(id) ON DELETE CASCADE,
  depends_on_id TEXT NOT NULL REFERENCES milestones(id) ON DELETE CASCADE,
  PRIMARY KEY (milestone_id, depends_on_id),
  CHECK (milestone_id <> depends_on_id)
);

-- ───────────────────────────── Tasks ─────────────────────────────

CREATE TABLE tasks (
  id                TEXT PRIMARY KEY,
  project_id        TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  milestone_id      TEXT REFERENCES milestones(id) ON DELETE SET NULL,
  number            INTEGER NOT NULL,
  title             TEXT NOT NULL,
  description       TEXT NOT NULL DEFAULT '',
  status            TEXT NOT NULL DEFAULT 'todo' CHECK (status IN ('backlog','todo','in_progress','in_review','blocked','completed','cancelled')),
  priority          TEXT NOT NULL DEFAULT 'medium' CHECK (priority IN ('low','medium','high','urgent')),
  responsible_id    TEXT REFERENCES users(id) ON DELETE SET NULL,
  start_date        TEXT,
  due_date          TEXT,
  estimate_hours    REAL CHECK (estimate_hours IS NULL OR estimate_hours >= 0),
  weight            REAL NOT NULL DEFAULT 1 CHECK (weight > 0),
  requires_approval INTEGER NOT NULL DEFAULT 1,
  blocked_reason    TEXT,
  sort_order        REAL NOT NULL DEFAULT 0,
  created_by        TEXT REFERENCES users(id),
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  submitted_at      TEXT,
  completed_at      TEXT,
  approved_by       TEXT REFERENCES users(id),
  cancelled_at      TEXT,
  UNIQUE (project_id, number)
);
CREATE INDEX idx_tasks_project_status ON tasks(project_id, status);
CREATE INDEX idx_tasks_responsible ON tasks(responsible_id, status);
CREATE INDEX idx_tasks_due ON tasks(due_date);
CREATE INDEX idx_tasks_milestone ON tasks(milestone_id);

CREATE TABLE task_assignees (
  task_id  TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  user_id  TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  added_at TEXT NOT NULL,
  PRIMARY KEY (task_id, user_id)
);
CREATE INDEX idx_task_assignees_user ON task_assignees(user_id);

CREATE TABLE subtasks (
  id         TEXT PRIMARY KEY,
  task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  title      TEXT NOT NULL,
  done       INTEGER NOT NULL DEFAULT 0,
  done_at    TEXT,
  done_by    TEXT REFERENCES users(id),
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_subtasks_task ON subtasks(task_id);

CREATE TABLE task_dependencies (
  task_id            TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  depends_on_task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  created_at         TEXT NOT NULL,
  PRIMARY KEY (task_id, depends_on_task_id),
  CHECK (task_id <> depends_on_task_id)
);
CREATE INDEX idx_task_deps_reverse ON task_dependencies(depends_on_task_id);

CREATE TABLE task_status_history (
  id          TEXT PRIMARY KEY,
  task_id     TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  from_status TEXT,
  to_status   TEXT NOT NULL,
  note        TEXT NOT NULL DEFAULT '',
  changed_by  TEXT REFERENCES users(id),
  changed_at  TEXT NOT NULL
);
CREATE INDEX idx_task_status_history_task ON task_status_history(task_id, changed_at);
CREATE INDEX idx_task_status_history_period ON task_status_history(changed_at, to_status);

CREATE TABLE task_submissions (
  id            TEXT PRIMARY KEY,
  task_id       TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  submitted_by  TEXT NOT NULL REFERENCES users(id),
  note          TEXT NOT NULL DEFAULT '',
  submitted_at  TEXT NOT NULL,
  decision      TEXT NOT NULL DEFAULT 'pending' CHECK (decision IN ('pending','approved','revision_requested','withdrawn')),
  decided_by    TEXT REFERENCES users(id),
  decided_at    TEXT,
  decision_note TEXT NOT NULL DEFAULT ''
);
CREATE INDEX idx_task_submissions_task ON task_submissions(task_id, submitted_at);
CREATE INDEX idx_task_submissions_pending ON task_submissions(decision);

CREATE TABLE time_entries (
  id         TEXT PRIMARY KEY,
  task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  work_date  TEXT NOT NULL,
  minutes    INTEGER NOT NULL CHECK (minutes > 0 AND minutes <= 1440),
  note       TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_time_entries_task ON time_entries(task_id);
CREATE INDEX idx_time_entries_user_date ON time_entries(user_id, work_date);
CREATE INDEX idx_time_entries_project_date ON time_entries(project_id, work_date);

-- Internal-only discussion. Never exposed to the client portal.
CREATE TABLE comments (
  id          TEXT PRIMARY KEY,
  entity_type TEXT NOT NULL CHECK (entity_type IN ('task','project','deliverable')),
  entity_id   TEXT NOT NULL,
  project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  author_id   TEXT NOT NULL REFERENCES users(id),
  body        TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  edited_at   TEXT,
  deleted_at  TEXT
);
CREATE INDEX idx_comments_entity ON comments(entity_type, entity_id, created_at);

-- ───────────────────────────── Files & deliverables ─────────────────────────────

CREATE TABLE deliverables (
  id                 TEXT PRIMARY KEY,
  project_id         TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  task_id            TEXT REFERENCES tasks(id) ON DELETE SET NULL,
  milestone_id       TEXT REFERENCES milestones(id) ON DELETE SET NULL,
  title              TEXT NOT NULL,
  description        TEXT NOT NULL DEFAULT '',
  status             TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','in_review','approved','shared','client_approved','changes_requested')),
  current_version    INTEGER NOT NULL DEFAULT 0,
  approved_by        TEXT REFERENCES users(id),
  approved_at        TEXT,
  shared_by          TEXT REFERENCES users(id),
  shared_at          TEXT,
  client_decision_at TEXT,
  created_by         TEXT REFERENCES users(id),
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL
);
CREATE INDEX idx_deliverables_project ON deliverables(project_id, status);

CREATE TABLE attachments (
  id             TEXT PRIMARY KEY,
  project_id     TEXT REFERENCES projects(id) ON DELETE CASCADE,
  task_id        TEXT REFERENCES tasks(id) ON DELETE SET NULL,
  deliverable_id TEXT REFERENCES deliverables(id) ON DELETE CASCADE,
  client_id      TEXT REFERENCES clients(id) ON DELETE CASCADE,
  version        INTEGER NOT NULL DEFAULT 1,
  file_name      TEXT NOT NULL,
  content_type   TEXT NOT NULL,
  size_bytes     INTEGER NOT NULL CHECK (size_bytes > 0),
  storage_key    TEXT NOT NULL UNIQUE,          -- random, non-guessable R2 key
  sha256         TEXT NOT NULL,
  client_visible INTEGER NOT NULL DEFAULT 0,    -- only meaningful for deliverable versions that were shared
  uploaded_by    TEXT REFERENCES users(id),
  created_at     TEXT NOT NULL,
  deleted_at     TEXT,
  deleted_by     TEXT REFERENCES users(id)
);
CREATE INDEX idx_attachments_project ON attachments(project_id, deleted_at);
CREATE INDEX idx_attachments_task ON attachments(task_id);
CREATE INDEX idx_attachments_deliverable ON attachments(deliverable_id, version);

-- ───────────────────────────── Client portal ─────────────────────────────

CREATE TABLE client_access_tokens (
  id           TEXT PRIMARY KEY,
  client_id    TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  project_id   TEXT REFERENCES projects(id) ON DELETE CASCADE,  -- NULL = every non-archived project of the client
  contact_id   TEXT REFERENCES client_contacts(id) ON DELETE SET NULL,
  label        TEXT NOT NULL,
  token_hash   TEXT NOT NULL UNIQUE,           -- SHA-256 of the link secret
  token_hint   TEXT NOT NULL,                  -- last 4 characters, for identification only
  expires_at   TEXT NOT NULL,
  revoked_at   TEXT,
  revoked_by   TEXT REFERENCES users(id),
  last_used_at TEXT,
  use_count    INTEGER NOT NULL DEFAULT 0,
  created_by   TEXT REFERENCES users(id),
  created_at   TEXT NOT NULL
);
CREATE INDEX idx_client_tokens_client ON client_access_tokens(client_id);

CREATE TABLE portal_sessions (
  id              TEXT PRIMARY KEY,
  token_hash      TEXT NOT NULL UNIQUE,
  access_token_id TEXT NOT NULL REFERENCES client_access_tokens(id) ON DELETE CASCADE,
  client_id       TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  verified_at     TEXT NOT NULL,                -- last step-up verification (for sensitive actions)
  verified_email  TEXT,
  created_at      TEXT NOT NULL,
  last_seen_at    TEXT NOT NULL,
  expires_at      TEXT NOT NULL,
  revoked_at      TEXT,
  ip              TEXT,
  user_agent      TEXT
);
CREATE INDEX idx_portal_sessions_token ON portal_sessions(access_token_id);

CREATE TABLE client_feedback (
  id                TEXT PRIMARY KEY,
  project_id        TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  client_id         TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  deliverable_id    TEXT REFERENCES deliverables(id) ON DELETE SET NULL,
  portal_session_id TEXT REFERENCES portal_sessions(id) ON DELETE SET NULL,
  author_name       TEXT NOT NULL,
  author_email      TEXT,
  kind              TEXT NOT NULL CHECK (kind IN ('feedback','revision_request','approval','question')),
  body              TEXT NOT NULL,
  status            TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','acknowledged','resolved')),
  response          TEXT,                       -- client-visible reply
  responded_by      TEXT REFERENCES users(id),
  responded_at      TEXT,
  created_at        TEXT NOT NULL
);
CREATE INDEX idx_client_feedback_project ON client_feedback(project_id, status);

-- ───────────────────────────── Calendar & HR ─────────────────────────────

CREATE TABLE calendar_events (
  id               TEXT PRIMARY KEY,
  title            TEXT NOT NULL,
  description      TEXT NOT NULL DEFAULT '',
  kind             TEXT NOT NULL CHECK (kind IN ('internal_meeting','client_meeting','company_event','deadline','reminder','other')),
  start_at         TEXT NOT NULL,
  end_at           TEXT NOT NULL,
  all_day          INTEGER NOT NULL DEFAULT 0,
  location         TEXT,
  project_id       TEXT REFERENCES projects(id) ON DELETE CASCADE,
  client_id        TEXT REFERENCES clients(id) ON DELETE SET NULL,
  department_id    TEXT REFERENCES departments(id) ON DELETE SET NULL,
  organizer_id     TEXT REFERENCES users(id) ON DELETE SET NULL,
  visibility       TEXT NOT NULL DEFAULT 'company' CHECK (visibility IN ('company','department','project','attendees')),
  recurrence_rule  TEXT,                        -- RFC 5545 subset: FREQ=DAILY|WEEKLY|MONTHLY;INTERVAL=n;BYDAY=..;UNTIL=YYYYMMDD;COUNT=n
  reminder_minutes INTEGER,
  is_seed          INTEGER NOT NULL DEFAULT 0,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  cancelled_at     TEXT,
  CHECK (end_at >= start_at)
);
CREATE INDEX idx_calendar_events_range ON calendar_events(start_at, end_at);
CREATE INDEX idx_calendar_events_project ON calendar_events(project_id);

CREATE TABLE event_attendees (
  event_id TEXT NOT NULL REFERENCES calendar_events(id) ON DELETE CASCADE,
  user_id  TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  response TEXT NOT NULL DEFAULT 'pending' CHECK (response IN ('pending','accepted','declined')),
  PRIMARY KEY (event_id, user_id)
);
CREATE INDEX idx_event_attendees_user ON event_attendees(user_id);

CREATE TABLE holidays (
  id               TEXT PRIMARY KEY,
  holiday_date     TEXT NOT NULL,
  year             INTEGER NOT NULL,
  name             TEXT NOT NULL,
  kind             TEXT NOT NULL CHECK (kind IN ('national','state','company','closure','optional')),
  region           TEXT NOT NULL DEFAULT 'IN',  -- IN, IN-TN, COMPANY
  is_day_off       INTEGER NOT NULL DEFAULT 1,  -- optional/restricted holidays may be 0
  source           TEXT NOT NULL DEFAULT '',    -- e.g. "TN G.O.(Ms) No. …, Public (Misc.) Dept."
  source_url       TEXT,
  status           TEXT NOT NULL DEFAULT 'pending_verification' CHECK (status IN ('pending_verification','verified','rejected')),
  verified_by      TEXT REFERENCES users(id),
  verified_at      TEXT,
  created_by       TEXT REFERENCES users(id),
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  UNIQUE (holiday_date, name)
);
CREATE INDEX idx_holidays_date ON holidays(holiday_date, status);

-- Explicit exceptions to the configured working-day rules (e.g. a compensatory working Saturday).
CREATE TABLE working_day_overrides (
  override_date TEXT PRIMARY KEY,
  is_working    INTEGER NOT NULL CHECK (is_working IN (0,1)),
  reason        TEXT NOT NULL,
  created_by    TEXT REFERENCES users(id),
  created_at    TEXT NOT NULL
);

CREATE TABLE leave_types (
  id                TEXT PRIMARY KEY,
  code              TEXT NOT NULL UNIQUE,
  name              TEXT NOT NULL,
  annual_quota      REAL,                       -- NULL = not tracked against a balance
  is_paid           INTEGER NOT NULL DEFAULT 1,
  active            INTEGER NOT NULL DEFAULT 1,
  created_at        TEXT NOT NULL
);

CREATE TABLE leave_balances (
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  leave_type_id TEXT NOT NULL REFERENCES leave_types(id) ON DELETE CASCADE,
  year          INTEGER NOT NULL,
  allocated     REAL NOT NULL,
  adjustment    REAL NOT NULL DEFAULT 0,
  note          TEXT NOT NULL DEFAULT '',
  updated_at    TEXT NOT NULL,
  PRIMARY KEY (user_id, leave_type_id, year)
);

CREATE TABLE leave_requests (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  leave_type_id TEXT NOT NULL REFERENCES leave_types(id),
  start_date    TEXT NOT NULL,
  end_date      TEXT NOT NULL,
  half_day      TEXT NOT NULL DEFAULT 'none' CHECK (half_day IN ('none','first_half','second_half')),
  days          REAL NOT NULL,                  -- working days, computed with holiday/working-day rules
  reason        TEXT NOT NULL DEFAULT '',
  status        TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','cancelled')),
  decided_by    TEXT REFERENCES users(id),
  decided_at    TEXT,
  decision_note TEXT NOT NULL DEFAULT '',
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  CHECK (end_date >= start_date)
);
CREATE INDEX idx_leave_requests_user ON leave_requests(user_id, start_date);
CREATE INDEX idx_leave_requests_status ON leave_requests(status, start_date);

CREATE TABLE attendance_records (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  work_date    TEXT NOT NULL,
  check_in_at  TEXT,
  check_out_at TEXT,
  status       TEXT NOT NULL CHECK (status IN ('present','half_day','absent','remote')),
  source       TEXT NOT NULL DEFAULT 'self' CHECK (source IN ('self','manual','correction')),
  note         TEXT NOT NULL DEFAULT '',
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  updated_by   TEXT REFERENCES users(id),
  UNIQUE (user_id, work_date)
);
CREATE INDEX idx_attendance_date ON attendance_records(work_date);

CREATE TABLE attendance_corrections (
  id                  TEXT PRIMARY KEY,
  user_id             TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  work_date           TEXT NOT NULL,
  requested_check_in  TEXT,
  requested_check_out TEXT,
  requested_status    TEXT NOT NULL CHECK (requested_status IN ('present','half_day','absent','remote')),
  reason              TEXT NOT NULL,
  status              TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),
  decided_by          TEXT REFERENCES users(id),
  decided_at          TEXT,
  decision_note       TEXT NOT NULL DEFAULT '',
  created_at          TEXT NOT NULL
);
CREATE INDEX idx_attendance_corrections ON attendance_corrections(status, work_date);

-- ───────────────────────────── Notifications, audit, reporting, settings ─────────────────────────────

CREATE TABLE notifications (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind        TEXT NOT NULL,
  title       TEXT NOT NULL,
  body        TEXT NOT NULL DEFAULT '',
  link        TEXT,                              -- in-app path; target is re-authorised when opened
  entity_type TEXT,
  entity_id   TEXT,
  dedupe_key  TEXT,                              -- prevents duplicate scheduled reminders
  read_at     TEXT,
  created_at  TEXT NOT NULL
);
CREATE INDEX idx_notifications_user ON notifications(user_id, read_at, created_at);
CREATE UNIQUE INDEX uq_notifications_dedupe ON notifications(user_id, dedupe_key) WHERE dedupe_key IS NOT NULL;

CREATE TABLE notification_preferences (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind    TEXT NOT NULL,
  in_app  INTEGER NOT NULL DEFAULT 1,
  email   INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, kind)
);

CREATE TABLE activity_logs (
  id          TEXT PRIMARY KEY,
  category    TEXT NOT NULL DEFAULT 'activity' CHECK (category IN ('activity','security','admin')),
  actor_type  TEXT NOT NULL CHECK (actor_type IN ('user','client','system')),
  actor_id    TEXT,
  action      TEXT NOT NULL,
  entity_type TEXT,
  entity_id   TEXT,
  project_id  TEXT,
  summary     TEXT NOT NULL,
  changes     TEXT,                               -- JSON diff of changed fields
  ip          TEXT,
  created_at  TEXT NOT NULL
);
CREATE INDEX idx_activity_project ON activity_logs(project_id, created_at);
CREATE INDEX idx_activity_entity ON activity_logs(entity_type, entity_id, created_at);
CREATE INDEX idx_activity_category ON activity_logs(category, created_at);
CREATE INDEX idx_activity_actor ON activity_logs(actor_id, created_at);

CREATE TABLE report_snapshots (
  id           TEXT PRIMARY KEY,
  report_type  TEXT NOT NULL CHECK (report_type IN ('company','project','member','client')),
  scope_id     TEXT,
  period_start TEXT NOT NULL,
  period_end   TEXT NOT NULL,
  source       TEXT NOT NULL CHECK (source IN ('manual','scheduled')),
  payload      TEXT NOT NULL,                     -- frozen JSON report document
  generated_by TEXT REFERENCES users(id),
  generated_at TEXT NOT NULL
);
CREATE INDEX idx_report_snapshots ON report_snapshots(report_type, scope_id, period_start);

CREATE TABLE company_settings (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,                       -- JSON, validated per key by the Worker
  updated_by TEXT REFERENCES users(id),
  updated_at TEXT NOT NULL
);
